SELECT p.gender, p.anchor_age, p.anchor_year, p.dod, COUNT(DISTINCT a.hadm_id) AS admission_count, SUM(CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS death_count, PERCENT_RANK() OVER (ORDER BY hs_troponin_t) AS percentile_rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 64 AND 74 AND l.itemid = 817971 AND percentile_rank > 0.99 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.dod ORDER BY admission_count DESC NULLS LAST;